// Normalize the cancellation event. Expected body:
// slot_start (ISO), practitioner, treatment, duration_min
const b = $input.first().json.body || $input.first().json;
if (!b.slot_start || isNaN(new Date(b.slot_start).getTime())) {
  return [{ json: { ok: false, error: 'slot_start invalid' } }];
}
return [{
  json: {
    ok: true,
    slot_start: new Date(b.slot_start).toISOString(),
    practitioner: b.practitioner || 'any',
    treatment: b.treatment || 'any',
    duration_min: Number(b.duration_min) || 60,
    released_at: new Date().toISOString()
  }
}];

// DEMO SOURCE. Replace with your waitlist sheet.
// Columns: customer_name, phone, wanted_treatment, flexible (bool), priority_score
const demoWaitlist = [
  { customer_name: 'Lisa Mertens', phone: '+316****5641', wanted_treatment: 'Haircut', flexible: true, priority_score: 9 },
  { customer_name: 'Daan Cox', phone: '+316****5642', wanted_treatment: 'Balayage', flexible: false, priority_score: 6 },
  { customer_name: 'Nina Blaauw', phone: '+316****5643', wanted_treatment: 'Haircut', flexible: true, priority_score: 7 },
  { customer_name: 'Sanne de Vries', phone: '+316****5644', wanted_treatment: 'Haircut', flexible: false, priority_score: 5 },
  { customer_name: 'Eline Koster', phone: '+316****5645', wanted_treatment: 'Balayage', flexible: true, priority_score: 7 },
  { customer_name: 'Mark Jansen', phone: '+316****5646', wanted_treatment: 'Haircut', flexible: true, priority_score: 5 }
];
return demoWaitlist.map((row) => ({ json: row }));

// Rank the waitlist for every slot row in this run.
// Slot rows come from the cancel arm ($('Normalize cancellation')) or the
// sweeper arm ($('Sweep: expired slots')); whichever executed wins.
// Per slot, everyone already offered (any round) or declined is excluded,
// so a re-offer moves DOWN the waitlist instead of looping on the top 3.
// Ranking: treatment match first, flexible next, then priority_score.
const sources = ['Sweep: expired slots', 'Normalize cancellation'];
let slotRows = [];
for (const name of sources) {
  try {
    const rows = $(name).all();
    if (rows.length) { slotRows = rows; break; }
  } catch (e) { /* arm not executed in this run */ }
}
if (!slotRows.length) return [];
const store = $getWorkflowStaticData('global') || {};
const book = store.offerBook || {};
const waitlist = $input.all();
const out = [];
for (const s of slotRows) {
  const slot = s.json;
  const entry = book[slot.slot_start];
  const exclude = entry
    ? [...(entry.offers || []).map((o) => o.who), ...(entry.declined || [])]
    : [];
  const ranked = waitlist
    .filter((w) => !exclude.includes(w.json.phone))
    .map((w) => {
      const r = w.json;
      let score = 0;
      if (slot.treatment !== 'any' && r.wanted_treatment === slot.treatment) score += 50;
      if (r.flexible) score += 20;
      score += Number(r.priority_score) || 0;
      return { json: { ...r, match_score: score } };
    })
    .sort((a, b) => b.json.match_score - a.json.match_score)
    .slice(0, 3);
  const slotStr = new Date(slot.slot_start).toLocaleString('en-GB', {
    weekday: 'long', hour: '2-digit', minute: '2-digit'
  });
  const source = slot.source || 'cancel';
  if (ranked.length === 0) {
    out.push({ json: {
      row_type: 'exhausted',
      slot_start: slot.slot_start,
      source: source,
      detail: 'waitlist exhausted: everyone was already offered or declined'
    } });
    continue;
  }
  const lead = source === 'sweep'
    ? 'a spot opened up earlier and is still free'
    : 'a spot just opened up';
  for (let i = 0; i < ranked.length; i++) {
    const e = ranked[i].json;
    out.push({ json: {
      ...e,
      row_type: 'offer',
      offer_position: i + 1,
      slot_start: slot.slot_start,
      practitioner: slot.practitioner,
      treatment: slot.treatment,
      duration_min: slot.duration_min,
      source: source,
      message: 'Hi ' + e.customer_name + ', ' + lead + ' ' + slotStr + ' with ' + slot.practitioner + '. You are on our waitlist. Want this spot? Reply TAKE within 30 minutes, after that it goes to the next person.'
    } });
  }
}
return out;

// Single writer for the offer state on the offer path.
// Shape: offerBook[slot_start] = { offers: [{who, at, round}], declined: [],
//   claimed_by, expires_at, exhausted, treatment, practitioner, duration_min }
// (The claim guard also writes claimed_by/declined atomically with its
// verdict; see that node. Same shape, documented in both places.)
// Offer rows are passed through for the send node; 'exhausted' rows mark
// the slot closed so the sweeper stops picking it up.
const store = $getWorkflowStaticData('global');
store.offerBook = store.offerBook || {};
const WINDOW_MS = 30 * 60 * 1000; // same 30 min as the offer message
const now = new Date();
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (r.row_type === 'exhausted') {
    const e = store.offerBook[r.slot_start] || {};
    e.exhausted = true;
    e.expires_at = null; // nothing left to sweep
    store.offerBook[r.slot_start] = e;
    out.push(item);
    continue;
  }
  const e = store.offerBook[r.slot_start] || { offers: [], declined: [], claimed_by: null };
  if (r.treatment) e.treatment = r.treatment;
  if (r.practitioner) e.practitioner = r.practitioner;
  if (r.duration_min) e.duration_min = r.duration_min;
  e.offers = e.offers || [];
  e.declined = e.declined || [];
  e.claimed_by = e.claimed_by || null;
  e.exhausted = false;
  e.offers.push({ who: r.phone, at: now.toISOString(), round: r.source || 'cancel' });
  e.expires_at = new Date(now.getTime() + WINDOW_MS).toISOString();
  store.offerBook[r.slot_start] = e;
  out.push(item);
}
return out;

// Placeholder for the send node (WhatsApp Business Cloud / SMS).
const items = $input.all();
return items.map((item) => ({ json: { ...item.json, sent_at: new Date().toISOString(), transport: 'demo' } }));

// Placeholder for the send node (WhatsApp Business Cloud / SMS).
const items = $input.all();
return items.map((item) => ({ json: { ...item.json, sent_at: new Date().toISOString(), transport: 'demo' } }));

// Sweeper summary: what this pass re-offered and what it closed out.
const rows = $input.all();
const reoffered = rows.filter((i) => i.json.row_type === 'offer').length;
const exhausted = rows.filter((i) => i.json.row_type === 'exhausted').length;
return [{ json: { swept_at: new Date().toISOString(), reoffered: reoffered, exhausted: exhausted } }];

// Validate the claim request body and PASS IT THROUGH for the guard.
// (An IF node forwards its input unchanged, so the guard downstream must
// receive the body here, not re-read the webhook node: the $('Node')
// lookup is not reliable for this in all n8n builds.)
const out = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const ok = !!(b.slot_start && !isNaN(new Date(b.slot_start).getTime()) && (b.phone || b.from));
  out.push({ json: { ok: ok, error: ok ? '' : 'slot_start or phone missing', body: ok ? b : null } });
}
return out;

// Claim guard: decide who gets the slot when TAKE replies arrive.
// State: claims[slot] = {phone, claimed_at} and the v2 offerBook entry
// (offers/declined/claimed_by/expires_at/exhausted, shape documented in
// the 'Offer book' node). This is the one node outside 'Offer book' that
// writes offerBook: the verdict decision and its state write must be one
// atomic step so the FIRST TAKE to reach this node wins (same reasoning
// as v1). On STOP or CANCEL the phone is persisted in declined[] and
// the slot is released immediately (expires_at = now) so the sweeper
// re-offers it to the next people instead of waiting out the clock.
// The read-check-write below is one synchronous step, so on a single
// self-hosted n8n instance the first TAKE wins and the second cleanly
// loses. On multi-worker queue mode, move this write to a conditional
// UPDATE in a transactional store instead.
const store = $getWorkflowStaticData('global');
store.claims = store.claims || {};
store.offerBook = store.offerBook || {};
const WINDOW_MS = 30 * 60 * 1000; // same 30 min as the offer message
const out = [];
// Input is the validated passthrough: {ok, error, body}.
for (const item of $input.all()) {
  const b = (item.json && item.json.body) || item.json;
  const slot = String(b.slot_start || '');
  const phone = String(b.phone || b.from || '').trim();
  const text = String(b.reply_text || b.Body || b.text || '').trim().toUpperCase();
  const offeredAt = b.offered_at ? new Date(b.offered_at).getTime() : null;
  let verdict, message;
  const existing = store.claims[slot];
  const book = store.offerBook[slot];

  if (/^(STOP|CANCEL|ANNULEREN)/.test(text)) {
    if (book) {
      book.declined = book.declined || [];
      if (!book.declined.includes(phone)) book.declined.push(phone);
      if (book.claimed_by === phone) book.claimed_by = null;
      book.expires_at = new Date().toISOString(); // release for the sweeper
    }
    if (existing && existing.phone === phone) {
      delete store.claims[slot];
      verdict = 'withdrawn';
      message = 'You are no longer on hold for this spot. Thanks for letting us know, we will offer it to someone else.';
    } else {
      verdict = 'no_claim';
      message = 'No active claim found for this number.';
    }
  } else if (!/^(TAKE|PAK)/.test(text)) {
    verdict = 'unclear';
    message = 'Reply TAKE to take the spot, or STOP to pass.';
  } else if (existing && existing.phone === phone) {
    verdict = 'already_yours'; // idempotent retry
    message = 'This spot is already reserved for you. See you then!';
  } else if (existing) {
    verdict = 'too_late';
    message = 'Sorry, someone else just took this spot. You are still on the waitlist.';
  } else if (offeredAt && Date.now() - offeredAt > WINDOW_MS) {
    verdict = 'expired';
    message = 'This spot is no longer available (the offer expired).';
  } else {
    store.claims[slot] = { phone: phone, claimed_at: new Date().toISOString() };
    if (book) {
      book.claimed_by = phone;
      book.expires_at = null; // claimed: nothing left to sweep
    }
    verdict = 'claimed';
    message = 'Done, the spot is yours! You will receive a confirmation with the details.';
  }

  out.push({ json: {
    slot_start: slot,
    from: phone,
    raw_text: text,
    verdict: verdict,
    message: message
  } });
}
return out;

// Sweeper: runs on a schedule, no input items. Emits one row per slot
// whose offer window expired without a claim. Slots with a holder or
// slots marked exhausted are skipped. Slot metadata stored at offer time
// lets the ranker re-rank without the original cancellation payload.
const store = $getWorkflowStaticData('global') || {};
const book = store.offerBook || {};
const out = [];
for (const slot of Object.keys(book)) {
  const e = book[slot];
  if (!e || e.exhausted || e.claimed_by) continue;
  if (!e.expires_at || new Date(e.expires_at).getTime() > Date.now()) continue;
  out.push({ json: {
    slot_start: slot,
    practitioner: e.practitioner || 'any',
    treatment: e.treatment || 'any',
    duration_min: e.duration_min || 60,
    source: 'sweep'
  } });
}
return out;
